const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-140, 0]); // 140°W, Equator
  const region = point.buffer(100000); // 100km buffer for ocean region

  // Time periods
  const aug1998 = ee.DateRange('1998-08-01', '1998-08-31');
  const dec1999 = ee.DateRange('1999-12-01', '1999-12-31');

  // 2. Data Acquisition - SeaWiFS Level-3 Ocean Color
  const seawifs = ee.ImageCollection('NASA/OCEANDATA/SeaWiFS/L3SMI')
    .select('chlor_a'); // Chlorophyll concentration

  // Filter for August 1998
  const aug1998Col = seawifs.filterDate(aug1998);
  const aug1998Size = aug1998Col.size().getInfo();

  // Filter for December 1999
  const dec1999Col = seawifs.filterDate(dec1999);
  const dec1999Size = dec1999Col.size().getInfo();

  console.log(`August 1998 Images: ${aug1998Size}`);
  console.log(`December 1999 Images: ${dec1999Size}`);

  // Check C1: Empty Collection
  if (aug1998Size === 0 || dec1999Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create monthly composites
  const aug1998Img = aug1998Col.mean();
  const dec1999Img = dec1999Col.mean();

  // 3. Processing - Count valid pixels
  const augCount = aug1998Img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const decCount = dec1999Img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`August 1998 Valid Pixels: ${augCount}`);
  console.log(`December 1999 Valid Pixels: ${decCount}`);

  // Check C2: No Valid Pixels
  if (augCount === 0 || decCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Mean chlorophyll values
  const augMean = aug1998Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const decMean = dec1999Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`August 1998 Mean Chl: ${augMean?.toFixed(4)} mg/m³`);
  console.log(`December 1999 Mean Chl: ${decMean?.toFixed(4)} mg/m³`);

  // 5. Validation & Final Answer
  // Check C3: Calculation Failure
  if (augMean === null || decMean === null || 
      isNaN(augMean) || isNaN(decMean) ||
      augMean < 0 || decMean < 0 || // Chlorophyll can't be negative
      augMean > 30 || decMean > 30) { // Unrealistically high chlorophyll
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values: Decrease means Dec 1999 < Aug 1998
  if (decMean < augMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
